struct ThermalDial { threshold: u8, revision: u8 }
fn adjust_threshold(location: ref<write,u8>, replacement: u8) -> u8 {
    let removed = replace(location, replacement);
    return removed;
}
fn yield_spoke(edge: ref<write,Option<ptr<LedgerSpoke>>>, target: ptr<LedgerSpoke>, ticket: Allocation, region_life: LifetimeDomain) -> LiveTail {
    let previous_edge = replace(edge, Option<ptr<LedgerSpoke>>::None);
    return LiveTail { owned_ptr: target, owned_allocation: ticket, owned_domain: region_life };
}
fn retire_spoke(target: ptr<LedgerSpoke>, ticket: Allocation, region_life: LifetimeDomain) -> unit {
    loan_read(region_life) { |stable| let checked = ref_from_ptr(read, target, stable); unit };
    let vacant = loan_exclusive_read(region_life) { |ending| destroy(target, ending) };
    let recovered = erase_slot<LedgerSpoke>(vacant);
    finalize_domain(region_life);
    deallocate(ticket, recovered);
    unit
}
fn main() -> unit {
    let sensor = ThermalDial { revision: u8(23), threshold: u8(41) };
    let backup = ThermalDial { threshold: u8(7), revision: u8(132) };
    let removed = loan_write(sensor@threshold) { |writer| adjust_threshold(writer, u8(86)) };
    let overwritten = loan_write(backup@revision) { |writer| adjust_threshold(writer, removed) };
    let after_sensor = sensor@threshold;
    let after_backup = backup@revision;
    let untouched_sensor = sensor@revision;
    let untouched_backup = backup@threshold;
    match try_allocate_one<LedgerSpoke>() {
        None => { unit },
        Some(first_package) => {
            let OneBacking { allocation, raw } = first_package;
            let first_ticket = allocation;
            let first_slot = into_slot<LedgerSpoke>(raw);
            let first_life = lifetime_domain();
            let first_ptr = loan_read(first_life) { |stable| initialize(first_slot, LedgerSpoke { successor: Option<ptr<LedgerSpoke>>::None, weight: u8(13) }, stable) };
            match try_allocate_one<LedgerSpoke>() {
                None => {
                    let first_empty = loan_exclusive_read(first_life) { |ending| destroy(first_ptr, ending) };
                    let first_raw = erase_slot<LedgerSpoke>(first_empty);
                    finalize_domain(first_life);
                    deallocate(first_ticket, first_raw);
                    unit
                },
                Some(second_package) => {
                    let OneBacking { allocation, raw } = second_package;
                    let second_ticket = allocation;
                    let second_slot = into_slot<LedgerSpoke>(raw);
                    let second_life = lifetime_domain();
                    let second_ptr = loan_read(second_life) { |stable| initialize(second_slot, LedgerSpoke { successor: Option<ptr<LedgerSpoke>>::None, weight: u8(197) }, stable) };
                    let replaced_link = loan_read(first_life) { |stable| let host = ref_from_ptr(write, first_ptr, stable); replace(host@successor, Option<ptr<LedgerSpoke>>::Some(second_ptr)) };
                    let inspected = loan_read(first_life) { |stable| let host = ref_from_ptr(read, first_ptr, stable); read(host@successor) };
                    match inspected { None => { unit }, Some(q) => { loan_read(second_life) { |stable| let witness = ref_from_ptr(read, q, stable); unit } } };
                    let LiveTail { owned_ptr, owned_allocation, owned_domain } = loan_read(first_life) { |stable| let host = ref_from_ptr(write, first_ptr, stable); yield_spoke(host@successor, second_ptr, second_ticket, second_life) };
                    loan_read(owned_domain) { |stable| let tail_alive = ref_from_ptr(read, owned_ptr, stable); unit };
                    retire_spoke(owned_ptr, owned_allocation, owned_domain);
                    let empty_first = loan_exclusive_read(first_life) { |ending| destroy(first_ptr, ending) };
                    let raw_first = erase_slot<LedgerSpoke>(empty_first);
                    finalize_domain(first_life);
                    deallocate(first_ticket, raw_first);
                    unit
                },
            }
        },
    }
}

